                    </div>

                    {/* Current Height */}
                    <div className="space-y-3">
                      <Label htmlFor="current-height" className="text-sm font-semibold text-gray-800 uppercase tracking-wide">
                        Current Height
                      </Label>
                      <div className="relative">
                        <Input
                          id="current-height"
