                      >
                        <SelectTrigger className="h-11 sm:h-12 md:h-14 lg:h-14 xl:h-16 2xl:h-16 border-2 border-gray-200 rounded-xl text-sm sm:text-base md:text-lg lg:text-lg xl:text-xl" data-testid="select-encoding">
