import { useState } from 'react';
import { Helmet } from 'react-helmet-async';
import Header from '@/components/Header';
import Footer from '@/components/Footer';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Card, CardContent } from '@/components/ui/card';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';

interface RetirementResult {
  totalSavings: number;
  monthlyContribution: number;
  totalContributions: number;
  interestEarned: number;
  monthlyIncomeAtRetirement: number;
  yearsOfContributions: number;
  currentSavingsGrowth: number;
  contributionsGrowth: number;
  interestPercentage: number;
  projectionSchedule: Array<{
    year: number;
    age: number;
    totalSavings: number;
    yearlyContribution: number;
    interestEarned: number;
  }>;
}

export default function RetirementCalculator() {
  const [currentAge, setCurrentAge] = useState('30');
  const [retirementAge, setRetirementAge] = useState('65');
  const [currentSavings, setCurrentSavings] = useState('50000');
  const [monthlyContribution, setMonthlyContribution] = useState('500');
  const [expectedReturn, setExpectedReturn] = useState('7');
  const [withdrawalRate, setWithdrawalRate] = useState('4');
  const [currency, setCurrency] = useState('USD');
  const [showProjection, setShowProjection] = useState(false);
  const [result, setResult] = useState<RetirementResult | null>(null);

  const calculateRetirement = () => {
    const currentAgeNum = parseFloat(currentAge);
    const retirementAgeNum = parseFloat(retirementAge);
    const currentSavingsNum = parseFloat(currentSavings) || 0;
    const monthlyContrib = parseFloat(monthlyContribution) || 0;
    const annualReturn = parseFloat(expectedReturn) / 100;
    const monthlyReturn = annualReturn / 12;
    const withdrawalRateNum = parseFloat(withdrawalRate) / 100;

    if (currentAgeNum <= 0 || retirementAgeNum <= 0 || retirementAgeNum <= currentAgeNum) return;

    const yearsToRetirement = retirementAgeNum - currentAgeNum;
    const monthsToRetirement = yearsToRetirement * 12;

    // Future value of current savings
    const currentSavingsGrowth = currentSavingsNum * Math.pow(1 + annualReturn, yearsToRetirement);

    // Future value of monthly contributions (annuity)
    let contributionsGrowth = 0;
    if (monthlyContrib > 0 && monthlyReturn > 0) {
      contributionsGrowth = monthlyContrib * 
        (Math.pow(1 + monthlyReturn, monthsToRetirement) - 1) / monthlyReturn;
    } else if (monthlyContrib > 0) {
      contributionsGrowth = monthlyContrib * monthsToRetirement;
    }

    const totalSavings = currentSavingsGrowth + contributionsGrowth;
    const totalContributions = currentSavingsNum + (monthlyContrib * monthsToRetirement);
    const interestEarned = totalSavings - totalContributions;
    const monthlyIncomeAtRetirement = (totalSavings * withdrawalRateNum) / 12;
    const interestPercentage = (interestEarned / totalSavings) * 100;

    // Generate projection schedule (showing every 5 years)
    const projectionSchedule = [];
    for (let year = 0; year <= yearsToRetirement; year += 5) {
      if (year > yearsToRetirement) year = yearsToRetirement;

      const yearsElapsed = year;
      const currentSavingsAtYear = currentSavingsNum * Math.pow(1 + annualReturn, yearsElapsed);
      const monthsElapsed = yearsElapsed * 12;

      let contributionsAtYear = 0;
      if (monthlyContrib > 0 && monthlyReturn > 0 && monthsElapsed > 0) {
        contributionsAtYear = monthlyContrib * 
          (Math.pow(1 + monthlyReturn, monthsElapsed) - 1) / monthlyReturn;
      } else if (monthlyContrib > 0) {
        contributionsAtYear = monthlyContrib * monthsElapsed;
      }

      const totalAtYear = currentSavingsAtYear + contributionsAtYear;
      const contributionsThisYear = monthlyContrib * 12;
      const interestThisYear = totalAtYear - (currentSavingsNum + (monthlyContrib * monthsElapsed));

      projectionSchedule.push({
        year: yearsElapsed,
        age: currentAgeNum + yearsElapsed,
        totalSavings: Math.round(totalAtYear * 100) / 100,
        yearlyContribution: contributionsThisYear,
        interestEarned: Math.max(0, Math.round(interestThisYear * 100) / 100)
      });

      if (year === yearsToRetirement) break;
    }

    setResult({
      totalSavings: Math.round(totalSavings * 100) / 100,
      monthlyContribution: monthlyContrib,
      totalContributions: Math.round(totalContributions * 100) / 100,
      interestEarned: Math.round(interestEarned * 100) / 100,
      monthlyIncomeAtRetirement: Math.round(monthlyIncomeAtRetirement * 100) / 100,
      yearsOfContributions: yearsToRetirement,
      currentSavingsGrowth: Math.round(currentSavingsGrowth * 100) / 100,
      contributionsGrowth: Math.round(contributionsGrowth * 100) / 100,
      interestPercentage: Math.round(interestPercentage * 100) / 100,
      projectionSchedule
    });
  };

  const resetCalculator = () => {
    setCurrentAge('30');
    setRetirementAge('65');
    setCurrentSavings('50000');
    setMonthlyContribution('500');
    setExpectedReturn('7');
    setWithdrawalRate('4');
    setCurrency('USD');
    setShowProjection(false);
    setResult(null);
  };

  const formatCurrency = (amount: number) => {
    const currencyMap: { [key: string]: { locale: string; currency: string } } = {
      USD: { locale: 'en-US', currency: 'USD' },
      EUR: { locale: 'de-DE', currency: 'EUR' },
      GBP: { locale: 'en-GB', currency: 'GBP' },
      INR: { locale: 'en-IN', currency: 'INR' },
      JPY: { locale: 'ja-JP', currency: 'JPY' },
      CAD: { locale: 'en-CA', currency: 'CAD' },
      AUD: { locale: 'en-AU', currency: 'AUD' },
      CNY: { locale: 'zh-CN', currency: 'CNY' },
      BRL: { locale: 'pt-BR', currency: 'BRL' },
      MXN: { locale: 'es-MX', currency: 'MXN' }
    };

    const config = currencyMap[currency] || currencyMap.USD;

    return new Intl.NumberFormat(config.locale, {
      style: 'currency',
      currency: config.currency,
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    }).format(amount);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-blue-50 to-indigo-50">
      <Helmet>
        <title>Retirement Calculator - Calculate Retirement Savings & Income | DapsiWow</title>
        <meta name="description" content="Free retirement calculator with 4% withdrawal rule, compound interest projections, and multi-currency support. Calculate 401k, IRA, and pension savings for secure retirement planning worldwide." />
        <meta name="keywords" content="retirement calculator, retirement planning calculator, 401k calculator, IRA calculator, pension calculator, retirement savings calculator, compound interest retirement, 4% withdrawal rule, retirement income calculator, financial independence calculator, early retirement calculator, retirement planning tool, retirement projections, retirement fund calculator, FIRE calculator, retirement age calculator, withdrawal rate calculator, retirement savings goals, retirement planning guide" />
        <meta property="og:title" content="Retirement Calculator - Calculate Retirement Savings & Income | DapsiWow" />
        <meta property="og:description" content="Free retirement planning calculator with 4% rule, compound interest calculations, and support for 401k, IRA & pension planning worldwide." />
        <meta property="og:type" content="website" />
        <meta name="robots" content="index, follow" />
        <meta name="author" content="DapsiWow" />
        <link rel="canonical" href="https://dapsiwow.com/tools/retirement-calculator" />
        <script type="application/ld+json">
          {JSON.stringify({
            "@context": "https://schema.org",
            "@type": "WebApplication",
            "name": "Retirement Calculator",
            "description": "Free retirement planning calculator with 4% withdrawal rule, compound interest calculations, and multi-currency support for 401k, IRA, and pension planning.",
            "url": "https://dapsiwow.com/tools/retirement-calculator",
            "applicationCategory": "FinanceApplication",
            "operatingSystem": "Any",
            "offers": {
              "@type": "Offer",
              "price": "0",
              "priceCurrency": "USD"
            },
            "featureList": [
              "4% withdrawal rule calculations",
              "Compound interest projections",
              "Multi-currency support",
              "401k and IRA planning",
              "Retirement income projections",
              "Financial independence planning"
            ]
          })}
        </script>
      </Helmet>

      <Header />

      <main>
        {/* Hero Section */}
        <section className="relative py-8 sm:py-12 md:py-16 lg:py-20 xl:py-24 2xl:py-32 overflow-hidden">
          <div className="absolute inset-0 bg-gradient-to-br from-blue-600/10 to-indigo-600/20"></div>
          <div className="relative max-w-5xl mx-auto px-3 sm:px-4 md:px-6 lg:px-8 text-center">
            <div className="space-y-4 sm:space-y-6 md:space-y-8">
              <div className="inline-flex items-center px-2 sm:px-3 md:px-4 py-1 sm:py-1.5 md:py-2 bg-white/80 backdrop-blur-sm rounded-full border border-blue-200">
                <span className="text-xs sm:text-sm font-medium text-blue-700">Professional Retirement Calculator</span>
              </div>
              <h1 className="text-2xl sm:text-3xl md:text-4xl lg:text-5xl xl:text-6xl 2xl:text-7xl font-bold text-slate-900 leading-tight tracking-tight px-2 sm:px-0" data-testid="page-title">
                <span className="block">Smart Retirement</span>
                <span className="block text-transparent bg-clip-text bg-gradient-to-r from-blue-600 to-indigo-600 mt-1 sm:mt-2">
                  Calculator
                </span>
              </h1>
              <p className="text-xs sm:text-sm md:text-base lg:text-lg xl:text-xl 2xl:text-2xl text-slate-600 max-w-xs sm:max-w-sm md:max-w-lg lg:max-w-2xl xl:max-w-3xl 2xl:max-w-4xl mx-auto leading-relaxed px-3 sm:px-2 md:px-0">
                Plan your retirement savings with advanced compound interest calculations and the proven 4% withdrawal rule
              </p>
            </div>
          </div>
        </section>

        <div className="w-full max-w-7xl mx-auto px-3 sm:px-4 md:px-6 lg:px-8 py-6 sm:py-8 md:py-12 lg:py-16">
          {/* Main Calculator Card */}
          <Card className="bg-white/90 backdrop-blur-sm shadow-2xl border-0 rounded-xl sm:rounded-2xl md:rounded-3xl overflow-hidden">
            <CardContent className="p-0">
              <div className="flex flex-col">
                {/* Input Section */}
                <div className="p-3 sm:p-4 md:p-6 lg:p-8 xl:p-10 2xl:p-12 space-y-4 sm:space-y-6 md:space-y-8">
                  <div className="text-center sm:text-left">
                    <h2 className="text-xl sm:text-2xl md:text-3xl font-bold text-gray-900 mb-1 sm:mb-2">Retirement Configuration</h2>
                    <p className="text-sm sm:text-base text-gray-600">Enter your retirement planning details for accurate projections</p>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 sm:gap-4 md:gap-6">
                    {/* Currency Selection */}
                    <div className="space-y-2 sm:space-y-3">
                      <Label htmlFor="currency" className="text-xs sm:text-sm font-semibold text-gray-800 uppercase tracking-wide">
                        Currency
                      </Label>
                      <Select value={currency} onValueChange={setCurrency}>
                        <SelectTrigger className="h-10 sm:h-12 md:h-14 border-2 border-gray-200 rounded-lg sm:rounded-xl text-sm sm:text-base md:text-lg w-full" data-testid="select-currency">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="USD">USD - US Dollar</SelectItem>
                          <SelectItem value="EUR">EUR - Euro</SelectItem>
                          <SelectItem value="GBP">GBP - British Pound</SelectItem>
                          <SelectItem value="INR">INR - Indian Rupee</SelectItem>
                          <SelectItem value="JPY">JPY - Japanese Yen</SelectItem>
                          <SelectItem value="CAD">CAD - Canadian Dollar</SelectItem>
                          <SelectItem value="AUD">AUD - Australian Dollar</SelectItem>
                          <SelectItem value="CNY">CNY - Chinese Yuan</SelectItem>
                          <SelectItem value="BRL">BRL - Brazilian Real</SelectItem>
                          <SelectItem value="MXN">MXN - Mexican Peso</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>

                    {/* Current Age */}
                    <div className="space-y-2 sm:space-y-3">
                      <Label htmlFor="current-age" className="text-xs sm:text-sm font-semibold text-gray-800 uppercase tracking-wide">
                        Current Age
                      </Label>
                      <Input
                        id="current-age"
                        type="number"
                        value={currentAge}
                        onChange={(e) => setCurrentAge(e.target.value)}
                        className="h-10 sm:h-12 md:h-14 text-sm sm:text-base md:text-lg border-2 border-gray-200 rounded-lg sm:rounded-xl focus:border-blue-500 focus:ring-blue-500 w-full"
                        placeholder="30"
                        min="18"
                        max="100"
                        data-testid="input-current-age"
                      />
                    </div>

                    {/* Retirement Age */}
                    <div className="space-y-2 sm:space-y-3">
                      <Label htmlFor="retirement-age" className="text-xs sm:text-sm font-semibold text-gray-800 uppercase tracking-wide">
                        Planned Retirement Age
                      </Label>
                      <Input
                        id="retirement-age"
                        type="number"
                        value={retirementAge}
                        onChange={(e) => setRetirementAge(e.target.value)}
                        className="h-10 sm:h-12 md:h-14 text-sm sm:text-base md:text-lg border-2 border-gray-200 rounded-lg sm:rounded-xl focus:border-blue-500 focus:ring-blue-500 w-full"
                        placeholder="65"
                        min="50"
                        max="100"
                        data-testid="input-retirement-age"
                      />
                    </div>

                    {/* Current Savings */}
                    <div className="space-y-2 sm:space-y-3">
                      <Label htmlFor="current-savings" className="text-xs sm:text-sm font-semibold text-gray-800 uppercase tracking-wide">
                        Current Retirement Savings
                      </Label>
                      <div className="relative">
                        <span className="absolute left-3 sm:left-4 top-1/2 -translate-y-1/2 text-gray-500 text-sm sm:text-base md:text-lg">$</span>
                        <Input
                          id="current-savings"
                          type="number"
                          value={currentSavings}
                          onChange={(e) => setCurrentSavings(e.target.value)}
                          className="h-10 sm:h-12 md:h-14 pl-6 sm:pl-8 text-sm sm:text-base md:text-lg border-2 border-gray-200 rounded-lg sm:rounded-xl focus:border-blue-500 focus:ring-blue-500 w-full"
                          placeholder="50,000"
                          min="0"
                          step="100"
                          data-testid="input-current-savings"
                        />
                      </div>
                    </div>

                    {/* Monthly Contribution */}
                    <div className="space-y-2 sm:space-y-3">
                      <Label htmlFor="monthly-contribution" className="text-xs sm:text-sm font-semibold text-gray-800 uppercase tracking-wide">
                        Monthly Contribution
                      </Label>
                      <div className="relative">
                        <span className="absolute left-3 sm:left-4 top-1/2 -translate-y-1/2 text-gray-500 text-sm sm:text-base md:text-lg">$</span>
                        <Input
                          id="monthly-contribution"
                          type="number"
                          value={monthlyContribution}
                          onChange={(e) => setMonthlyContribution(e.target.value)}
                          className="h-10 sm:h-12 md:h-14 pl-6 sm:pl-8 text-sm sm:text-base md:text-lg border-2 border-gray-200 rounded-lg sm:rounded-xl focus:border-blue-500 focus:ring-blue-500 w-full"
                          placeholder="500"
                          min="0"
                          step="10"
                          data-testid="input-monthly-contribution"
                        />
                      </div>
                    </div>

                    {/* Expected Annual Return */}
                    <div className="space-y-2 sm:space-y-3">
                      <Label htmlFor="expected-return" className="text-xs sm:text-sm font-semibold text-gray-800 uppercase tracking-wide">
                        Expected Annual Return
                      </Label>
                      <div className="relative">
                        <Input
                          id="expected-return"
                          type="number"
                          value={expectedReturn}
                          onChange={(e) => setExpectedReturn(e.target.value)}
                          className="h-10 sm:h-12 md:h-14 pr-6 sm:pr-8 text-sm sm:text-base md:text-lg border-2 border-gray-200 rounded-lg sm:rounded-xl focus:border-blue-500 focus:ring-blue-500 w-full"
                          placeholder="7"
                          min="0"
                          max="20"
                          step="0.1"
                          data-testid="input-expected-return"
                        />
                        <span className="absolute right-3 sm:right-4 top-1/2 -translate-y-1/2 text-gray-500 text-sm sm:text-base md:text-lg">%</span>
                      </div>
                    </div>

                    {/* Withdrawal Rate */}
                    <div className="space-y-2 sm:space-y-3">
                      <Label htmlFor="withdrawal-rate" className="text-xs sm:text-sm font-semibold text-gray-800 uppercase tracking-wide">
                        Safe Withdrawal Rate
                      </Label>
                      <div className="relative">
                        <Input
                          id="withdrawal-rate"
                          type="number"
                          value={withdrawalRate}
                          onChange={(e) => setWithdrawalRate(e.target.value)}
                          className="h-10 sm:h-12 md:h-14 pr-6 sm:pr-8 text-sm sm:text-base md:text-lg border-2 border-gray-200 rounded-lg sm:rounded-xl focus:border-blue-500 focus:ring-blue-500 w-full"
                          placeholder="4"
                          min="1"
                          max="10"
                          step="0.1"
                          data-testid="input-withdrawal-rate"
                        />
                        <span className="absolute right-3 sm:right-4 top-1/2 -translate-y-1/2 text-gray-500 text-sm sm:text-base md:text-lg">%</span>
                      </div>
                      <p className="text-xs sm:text-sm text-gray-500">
                        The 4% rule is commonly used for sustainable retirement withdrawals
                      </p>
                    </div>
                  </div>

                  {/* Action Buttons */}
                  <div className="flex flex-col sm:flex-row justify-center items-center gap-2 sm:gap-3 md:gap-4 pt-3 sm:pt-4 md:pt-6">
                    <Button
                      onClick={calculateRetirement}
                      className="w-full sm:w-auto h-10 sm:h-12 md:h-14 px-4 sm:px-6 md:px-8 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 text-white font-semibold text-sm sm:text-base md:text-lg rounded-lg sm:rounded-xl shadow-lg transition-colors duration-200"
                      data-testid="button-calculate"
                    >
                      Calculate Retirement
                    </Button>
                    <Button
                      onClick={resetCalculator}
                      variant="outline"
                      className="w-full sm:w-auto h-10 sm:h-12 md:h-14 px-4 sm:px-6 md:px-8 border-2 border-gray-300 text-gray-700 hover:bg-gray-50 font-semibold text-sm sm:text-base md:text-lg rounded-lg sm:rounded-xl"
                      data-testid="button-reset"
                    >
                      Reset
                    </Button>
                  </div>

                  {/* Advanced Options */}
                  {result && (
                    <div className="flex flex-wrap gap-2 sm:gap-3 pt-3 sm:pt-4">
                      <Button
                        onClick={() => setShowProjection(!showProjection)}
                        variant="outline"
                        className="h-8 sm:h-10 px-3 sm:px-4 text-xs sm:text-sm rounded-full"
                        data-testid="button-show-projection"
                      >
                        {showProjection ? 'Hide' : 'Show'} Retirement Projection
                      </Button>
                    </div>
                  )}
                </div>

                {/* Results Section */}
                <div className="bg-gradient-to-br from-gray-50 to-blue-50 p-3 sm:p-4 md:p-6 lg:p-8 xl:p-10 2xl:p-12">
                  <h2 className="text-lg sm:text-xl md:text-2xl font-bold text-gray-900 mb-4 sm:mb-6 md:mb-8">Retirement Projection</h2>

                  {result ? (
                    <div className="space-y-3 sm:space-y-4 md:space-y-6" data-testid="retirement-results">
                      {/* Total Savings Highlight */}
                      <div className="bg-white rounded-lg sm:rounded-xl md:rounded-2xl p-3 sm:p-4 md:p-6 shadow-lg border border-blue-100">
                        <div className="text-xs sm:text-sm font-semibold text-gray-600 uppercase tracking-wide mb-1 sm:mb-2">Total Retirement Savings</div>
                        <div className="text-2xl sm:text-3xl md:text-4xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-600 to-indigo-600 break-all" data-testid="text-total-savings">
                          {formatCurrency(result.totalSavings)}
                        </div>
                      </div>

                      {/* Monthly Income Highlight */}
