                  </ul>
                </div>

                <div className="bg-green-50 border-2 border-green-200 rounded-lg p-4 sm:p-6">
                  <h4 className="font-bold text-gray-900 mb-3 text-center text-lg">Compound Interest (Annual)</h4>
