                          <Select value={speedUnit} onValueChange={setSpeedUnit}>
                            <SelectTrigger className="h-14 w-24 border-2 border-gray-200 rounded-xl text-lg" data-testid="select-speed-unit">
                              <SelectValue />
                            </SelectTrigger>
                            <SelectContent>
