  handleNumbers: 'reverse' | 'preserve' | 'flip';
}

interface ReverseResult {
  originalText: string;
  reversedText: string;
  method: string;
  charCount: number;
  wordCount: number;
  lineCount: number;
  timestamp: Date;
}

const ReverseTextTool = () => {
  const [inputText, setInputText] = useState('');
  const [reverseResult, setReverseResult] = useState<ReverseResult | null>(null);
