            },
            "featureList": [
              "Generate paragraphs, sentences, or words",
              "Customizable text length",
              "Traditional Lorem ipsum start option",
              "Instant text generation",
              "Copy to clipboard functionality"
            ]
          })}
        </script>
      </Helmet>

      <Header />

      <main>
