import { useState } from 'react';
import { Helmet } from 'react-helmet-async';
import Header from '@/components/Header';
import Footer from '@/components/Footer';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Card, CardContent } from '@/components/ui/card';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';

interface DiscountResult {
  originalPrice: number;
  discountAmount: number;
  finalPrice: number;
  savingsAmount: number;
  savingsPercentage: number;
  discountType: string;
}

export default function DiscountCalculator() {
  const [originalPrice, setOriginalPrice] = useState('');
  const [discountPercent, setDiscountPercent] = useState('');
  const [discountAmount, setDiscountAmount] = useState('');
  const [calculationType, setCalculationType] = useState('percentage');
  const [currency, setCurrency] = useState('USD');
  const [result, setResult] = useState<DiscountResult | null>(null);

  const calculateDiscount = () => {
    const price = parseFloat(originalPrice);

    if (isNaN(price) || price <= 0) return;

    let discount = 0;
    let discountType = '';

    if (calculationType === 'percentage') {
      const percent = parseFloat(discountPercent);
      if (isNaN(percent) || percent < 0 || percent > 100) return;
      discount = (price * percent) / 100;
      discountType = `${percent}% discount`;
    } else {
      discount = parseFloat(discountAmount);
      if (isNaN(discount) || discount < 0 || discount > price) return;
      discountType = `${formatCurrency(discount)} discount`;
    }

    const finalPrice = price - discount;
    const savingsPercentage = (discount / price) * 100;

    setResult({
      originalPrice: Math.round(price * 100) / 100,
      discountAmount: Math.round(discount * 100) / 100,
      finalPrice: Math.round(finalPrice * 100) / 100,
      savingsAmount: Math.round(discount * 100) / 100,
      savingsPercentage: Math.round(savingsPercentage * 100) / 100,
      discountType
    });
  };

  const resetCalculator = () => {
    setOriginalPrice('');
    setDiscountPercent('');
    setDiscountAmount('');
    setCalculationType('percentage');
    setCurrency('USD');
    setResult(null);
  };

  const formatCurrency = (amount: number) => {
    const currencyMap: { [key: string]: { locale: string; currency: string } } = {
      USD: { locale: 'en-US', currency: 'USD' },
      EUR: { locale: 'de-DE', currency: 'EUR' },
      GBP: { locale: 'en-GB', currency: 'GBP' },
      INR: { locale: 'en-IN', currency: 'INR' },
      JPY: { locale: 'ja-JP', currency: 'JPY' },
      CAD: { locale: 'en-CA', currency: 'CAD' },
      AUD: { locale: 'en-AU', currency: 'AUD' },
      CNY: { locale: 'zh-CN', currency: 'CNY' },
      BRL: { locale: 'pt-BR', currency: 'BRL' },
      MXN: { locale: 'es-MX', currency: 'MXN' }
    };

    const config = currencyMap[currency] || currencyMap.USD;

    return new Intl.NumberFormat(config.locale, {
      style: 'currency',
      currency: config.currency,
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    }).format(amount);
  };

  // Calculate multiple discount scenarios for comparison
  const getCommonDiscounts = () => {
    const price = parseFloat(originalPrice);
    if (isNaN(price) || price <= 0) return [];

    const discounts = [10, 15, 20, 25, 30, 40, 50];
    return discounts.map(percent => ({
      percent,
      discount: (price * percent) / 100,
      final: price - (price * percent) / 100,
      savings: (price * percent) / 100
    }));
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-blue-50 to-indigo-50">
      <Helmet>
        <title>Discount Calculator - Sale Prices Instantly | DapsiWow</title>
        <meta name="description" content="Calculate discounts instantly. Get sale prices, savings, and percentage discounts for shopping and business. Multiple currencies supported. Start now!" />
        <meta name="keywords" content="discount calculator, sale price calculator, percentage discount calculator, savings calculator, price reduction calculator, shopping calculator, retail discount calculator, business discount tool, markdown calculator" />
        <meta property="og:title" content="Discount Calculator - Calculate Sale Prices & Savings Instantly | DapsiWow" />
        <meta property="og:description" content="Free discount calculator for calculating sale prices, discount amounts, and savings. Support for percentage and fixed amount discounts with multiple currencies worldwide." />
        <meta property="og:type" content="website" />
        <meta name="robots" content="index, follow" />
        <meta name="author" content="DapsiWow" />
        <link rel="canonical" href="https://dapsiwow.com/tools/discount-calculator" />
        <script type="application/ld+json">
          {JSON.stringify({
            "@context": "https://schema.org",
            "@type": "WebApplication",
            "name": "Discount Calculator",
            "description": "Free online discount calculator to calculate sale prices, discount amounts, and savings for shopping, business sales, and price comparisons. Features percentage and fixed amount discounts with multiple currency support.",
            "url": "https://dapsiwow.com/tools/discount-calculator",
            "applicationCategory": "CalculatorApplication",
            "operatingSystem": "Any",
            "offers": {
              "@type": "Offer",
              "price": "0",
              "priceCurrency": "USD"
            },
            "featureList": [
              "Percentage discount calculations",
              "Fixed amount discount calculations",
              "Multiple currency support",
              "Instant savings calculations",
              "Price comparison tools",
              "Business discount planning"
            ]
          })}
        </script>
      </Helmet>

      <Header />

      <main>
        {/* Hero Section */}
        <section className="relative py-12 sm:py-16 md:py-20 lg:py-24 xl:py-28 2xl:py-32 overflow-hidden">
          <div className="absolute inset-0 bg-gradient-to-br from-blue-600/10 to-indigo-600/20"></div>
          <div className="relative max-w-7xl mx-auto px-3 sm:px-4 md:px-6 lg:px-8 xl:px-12 text-center">
            <div className="space-y-4 sm:space-y-6 md:space-y-8 lg:space-y-10">
              <div className="inline-flex items-center px-3 py-1.5 sm:px-4 sm:py-2 md:px-5 md:py-2.5 bg-white/80 backdrop-blur-sm rounded-full border border-blue-200 text-xs sm:text-sm md:text-base">
                <span className="font-medium text-blue-700">Professional Discount Calculator</span>
              </div>
              <h1 className="text-2xl sm:text-3xl md:text-4xl lg:text-5xl xl:text-6xl 2xl:text-7xl font-bold text-slate-900 leading-tight tracking-tight">
                <span className="block">Smart Discount</span>
                <span className="block text-transparent bg-clip-text bg-gradient-to-r from-blue-600 to-indigo-600">
                  Calculator
                </span>
              </h1>
              <p className="text-sm sm:text-base md:text-lg lg:text-xl xl:text-2xl text-slate-600 max-w-xs sm:max-w-md md:max-w-2xl lg:max-w-4xl xl:max-w-5xl mx-auto leading-relaxed px-2 sm:px-4 md:px-6">
                Calculate sale prices, discount amounts, and savings with advanced features for shopping and business
              </p>
            </div>
          </div>
        </section>

        <div className="w-full max-w-7xl mx-auto px-3 sm:px-4 md:px-6 lg:px-8 py-6 sm:py-8 md:py-12 lg:py-16">
          {/* Main Calculator Card */}
          <Card className="bg-white/90 backdrop-blur-sm shadow-2xl border-0 rounded-xl sm:rounded-2xl md:rounded-3xl overflow-hidden">
            <CardContent className="p-0">
              <div className="flex flex-col lg:grid lg:grid-cols-3 gap-0">
                {/* Input Section */}
                <div className="lg:col-span-2 p-3 sm:p-4 md:p-6 lg:p-8 xl:p-10 2xl:p-12 space-y-4 sm:space-y-6 md:space-y-8">
                  <div className="text-center sm:text-left">
                    <h2 className="text-xl sm:text-2xl md:text-3xl font-bold text-gray-900 mb-1 sm:mb-2">Discount Configuration</h2>
                    <p className="text-sm sm:text-base text-gray-600">Enter price and discount details to calculate savings and final price</p>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-3 sm:gap-4 md:gap-6">
                    {/* Currency Selection */}
                    <div className="space-y-2 sm:space-y-3">
                      <Label htmlFor="currency" className="text-xs sm:text-sm font-semibold text-gray-800 uppercase tracking-wide">
                        Currency
                      </Label>
                      <Select value={currency} onValueChange={setCurrency}>
                        <SelectTrigger className="h-10 sm:h-12 md:h-14 border-2 border-gray-200 rounded-lg sm:rounded-xl text-sm sm:text-base md:text-lg w-full" data-testid="select-currency">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="USD">USD - US Dollar</SelectItem>
                          <SelectItem value="EUR">EUR - Euro</SelectItem>
                          <SelectItem value="GBP">GBP - British Pound</SelectItem>
                          <SelectItem value="INR">INR - Indian Rupee</SelectItem>
                          <SelectItem value="JPY">JPY - Japanese Yen</SelectItem>
                          <SelectItem value="CAD">CAD - Canadian Dollar</SelectItem>
                          <SelectItem value="AUD">AUD - Australian Dollar</SelectItem>
                          <SelectItem value="CNY">CNY - Chinese Yuan</SelectItem>
                          <SelectItem value="BRL">BRL - Brazilian Real</SelectItem>
                          <SelectItem value="MXN">MXN - Mexican Peso</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>

                    {/* Original Price */}
                    <div className="space-y-2 sm:space-y-3">
                      <Label htmlFor="original-price" className="text-xs sm:text-sm font-semibold text-gray-800 uppercase tracking-wide">
                        Original Price
                      </Label>
                      <div className="relative">
                        <span className="absolute left-3 sm:left-4 top-1/2 -translate-y-1/2 text-gray-500 text-sm sm:text-base md:text-lg">$</span>
                        <Input
                          id="original-price"
                          type="number"
                          value={originalPrice}
                          onChange={(e) => setOriginalPrice(e.target.value)}
                          className="h-10 sm:h-12 md:h-14 pl-7 sm:pl-8 text-sm sm:text-base md:text-lg border-2 border-gray-200 rounded-lg sm:rounded-xl focus:border-blue-500 focus:ring-blue-500 w-full"
                          placeholder="100.00"
                          min="0"
                          step="0.01"
                          data-testid="input-original-price"
                        />
                      </div>
                    </div>

                    {/* Discount Type */}
                    <div className="space-y-2 sm:space-y-3">
                      <Label className="text-xs sm:text-sm font-semibold text-gray-800 uppercase tracking-wide">
                        Discount Type
                      </Label>
                      <Select value={calculationType} onValueChange={setCalculationType}>
                        <SelectTrigger className="h-10 sm:h-12 md:h-14 border-2 border-gray-200 rounded-lg sm:rounded-xl text-sm sm:text-base md:text-lg w-full" data-testid="select-discount-type">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="percentage">Percentage Discount (%)</SelectItem>
                          <SelectItem value="amount">Fixed Amount Discount</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>

                    {/* Discount Value */}
                    {calculationType === 'percentage' ? (
                      <div className="space-y-2 sm:space-y-3">
                        <Label htmlFor="discount-percent" className="text-xs sm:text-sm font-semibold text-gray-800 uppercase tracking-wide">
                          Discount Percentage
                        </Label>
                        <div className="relative">
                          <Input
                            id="discount-percent"
                            type="number"
                            value={discountPercent}
                            onChange={(e) => setDiscountPercent(e.target.value)}
                            className="h-10 sm:h-12 md:h-14 pr-7 sm:pr-8 text-sm sm:text-base md:text-lg border-2 border-gray-200 rounded-lg sm:rounded-xl focus:border-blue-500 focus:ring-blue-500 w-full"
                            placeholder="20"
                            min="0"
                            max="100"
                            step="0.01"
                            data-testid="input-discount-percent"
                          />
                          <span className="absolute right-3 sm:right-4 top-1/2 -translate-y-1/2 text-gray-500 text-sm sm:text-base md:text-lg">%</span>
                        </div>
                      </div>
                    ) : (
                      <div className="space-y-2 sm:space-y-3">
                        <Label htmlFor="discount-amount" className="text-xs sm:text-sm font-semibold text-gray-800 uppercase tracking-wide">
                          Discount Amount
                        </Label>
                        <div className="relative">
                          <span className="absolute left-3 sm:left-4 top-1/2 -translate-y-1/2 text-gray-500 text-sm sm:text-base md:text-lg">$</span>
                          <Input
                            id="discount-amount"
                            type="number"
                            value={discountAmount}
                            onChange={(e) => setDiscountAmount(e.target.value)}
                            className="h-10 sm:h-12 md:h-14 pl-7 sm:pl-8 text-sm sm:text-base md:text-lg border-2 border-gray-200 rounded-lg sm:rounded-xl focus:border-blue-500 focus:ring-blue-500 w-full"
                            placeholder="20.00"
                            min="0"
                            step="0.01"
                            data-testid="input-discount-amount"
                          />
