import { useToast } from '@/hooks/use-toast';

export function AuthStatus() {
  const { user, logout, loading } = useAuth();
  const { toast } = useToast();

  if (loading) {
    return null;
  }

  if (!user) {
    return null;
  }

  const handleLogout = async () => {
    try {
      await logout();
      toast({
        title: 'Logged Out',
