            <p className="text-lg text-muted-foreground leading-relaxed">
              {content}
            </p>
          </CardContent>
        </Card>
      </div>
    </section>
  );
}

interface FAQ {
  question: string;
  answer: string;
}

interface FAQSectionProps {
  faqs: FAQ[];
}

export function FAQSection({ faqs }: FAQSectionProps) {
